with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as ITEM_CODE
        , VOLUNTARY_DEDUCT_RATE as PERCENTAGE_APPLIED
        , VOLUNTARY_DEDUCT_AMT as AMOUNT_APPLIED
        , cast(null as varchar) as JUSTIFICATION
        , 'BA_HCP_DT_PREMIUM' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_dt_premium') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as ITEM_CODE
        , cast(null as varchar) as PERCENTAGE_APPLIED
        , CLAIM_LOADING as AMOUNT_APPLIED
        , cast(null as varchar) as JUSTIFICATION
        , 'BA_HCP_POL_MST' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_pol_mst') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_REF))) as HUB_POLICY_HK
        , cast(null as varchar) as ITEM_CODE
        , COMMERCIAL_DISCOUNT_PER as PERCENTAGE_APPLIED
        , MEMBER_LOADING as AMOUNT_APPLIED
        , cast(null as varchar) as JUSTIFICATION
        , 'BJAZ_HEALTH_WEBSERVICE_INFO' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_health_webservice_info') }}
    where (nullif(trim(POLICY_REF),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as ITEM_CODE
        , COMMERCIAL_DISC_RATE as PERCENTAGE_APPLIED
        , COMMERCIAL_DISC_AMT as AMOUNT_APPLIED
        , REASON_FOR_DISCOUNT as JUSTIFICATION
        , 'BJAZ_ENROLL_SCR_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_enroll_scr_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , 'COMMERCIAL_DISC' as ITEM_CODE
        , cast(null as varchar) as PERCENTAGE_APPLIED
        , COMM_DISC as AMOUNT_APPLIED
        , cast(null as varchar) as JUSTIFICATION
        , 'BJAZ_STARPKG_POL_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_starpkg_pol_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , 'BRJ_LOADING' as ITEM_CODE
        , BRJ_LOAD_PER as PERCENTAGE_APPLIED
        , BRJ_LOAD_AMT as AMOUNT_APPLIED
        , cast(null as varchar) as JUSTIFICATION
        , 'BA_CCP_SUB_MATER_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ba_ccp_sub_mater_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , 'SPECIAL_DISCOUNT' as ITEM_CODE
        , cast(null as varchar) as PERCENTAGE_APPLIED
        , SPECIAL_DISC as AMOUNT_APPLIED
        , cast(null as varchar) as JUSTIFICATION
        , 'BJAZ_POLICY_SUMMARY' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_summary') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as ITEM_CODE
        , SERVICE_CHARGE_RATE as PERCENTAGE_APPLIED
        , ENDORSE_TERR_SURCHARGE as AMOUNT_APPLIED
        , ADD_LOAD_REASON as JUSTIFICATION
        , 'BJAZ_POLICY_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_bases_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        ITEM_CODE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then PERCENTAGE_APPLIED end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PERCENTAGE_APPLIED end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then PERCENTAGE_APPLIED end)) as PERCENTAGE_APPLIED,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then AMOUNT_APPLIED end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AMOUNT_APPLIED end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then AMOUNT_APPLIED end)) as AMOUNT_APPLIED,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then JUSTIFICATION end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then JUSTIFICATION end)) as JUSTIFICATION,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK, ITEM_CODE
),

hashed as (
    select
        *,
        case when ITEM_CODE is not null or PERCENTAGE_APPLIED is not null or AMOUNT_APPLIED is not null or JUSTIFICATION is not null
                     then md5(upper(coalesce(cast(ITEM_CODE as varchar), '') || '|' || coalesce(cast(PERCENTAGE_APPLIED as varchar), '') || '|' || coalesce(cast(AMOUNT_APPLIED as varchar), '') || '|' || coalesce(cast(JUSTIFICATION as varchar), '')))
                end as SAT_POLICY_DISCOUNT_LOADING_APPLIED_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_DISCOUNT_LOADING_APPLIED_HASHDIFF is not null
